private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 0x80) {
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            int c = (b & 0x1F) << 6;
            c |= bb.get() & 0x3F;
            sb.append((char) c);
        } else if ((b & 0xF0) == 0xE0) {
            int c = (b & 0x0F) << 12;
            c |= (bb.get() & 0x3F) << 6;
            c |= bb.get() & 0x3F;
            sb.append((char) c);
        } else if ((b & 0xF8) == 0xF0) {
            int c = (b & 0x07) << 18;
            c |= (bb.get() & 0x3F) << 12;
            c |= (bb.get() & 0x3F) << 6;
            c |= bb.get() & 0x3F;
            sb.append((char) c);
        } else {
            // Handle invalid UTF-8 sequence
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return i + sb.length();
}

