private void pop(final String descriptor) {
    Stack<String> outputFrameStack = new Stack<>();
    // Assuming the stack is already populated with abstract types
    // Pop as many abstract types from the output frame stack as described by the given descriptor
    for (char c : descriptor.toCharArray()) {
        if (c == 'I' || c == 'J' || c == 'F' || c == 'D' || c == 'Z' || c == 'C' || c == 'S' || c == 'B') {
            outputFrameStack.pop();
        } else if (c == 'L') {
            // Pop until 'L' is followed by ';'
            while (!outputFrameStack.isEmpty() && !outputFrameStack.peek().equals(";")) {
                outputFrameStack.pop();
            }
            if (!outputFrameStack.isEmpty()) {
                outputFrameStack.pop(); // Pop the ';'
            }
        } else if (c == '[') {
            // Pop until '[' is followed by a type descriptor
            while (!outputFrameStack.isEmpty() && outputFrameStack.peek().equals("[")) {
                outputFrameStack.pop();
            }
        }
    }
}

