        for (int i = start; i < end; i++) {
            Object type = currentFrame.get(i);
            if (type instanceof Integer) {
                stackMapTableEntries.add(((Integer) type).intValue());
            } else if (type instanceof Long) {
                stackMapTableEntries.add(((Long) type).longValue());
            } else if (type instanceof Float) {
                stackMapTableEntries.add(((Float) type).floatValue());
            } else if (type instanceof Double) {
                stackMapTableEntries.add(((Double) type).doubleValue());
            } else if (type instanceof String) {
                stackMapTableEntries.add(((String) type).intern());
            } else if (type instanceof Class<?>) {
                stackMapTableEntries.add(((Class<?>) type).getName());
            } else {
                throw new IllegalArgumentException("Unsupported type: " + type.getClass());
            }
        }
    }
}

