public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    Map<Character, Character> escapeMap = new HashMap<>();
    escapeMap.put('b', '\b');
    escapeMap.put('t', '\t');
    escapeMap.put('n', '\n');
    escapeMap.put('f', '\f');
    escapeMap.put('r', '\r');
    escapeMap.put('\"', '\"');
    escapeMap.put('\'', '\'');
    escapeMap.put('\\', '\\');

    StringBuilder result = new StringBuilder();
    boolean inEscape = false;

    for (char c : str.toCharArray()) {
        if (inEscape) {
            if (escapeMap.containsKey(c)) {
                result.append(escapeMap.get(c));
            } else {
                result.append('\\').append(c);
            }
            inEscape = false;
        } else if (c == '\\') {
            inEscape = true;
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

