protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = null;
    for (E edge : tour) {
        startVertex = graph.getEdgeSource(edge);
        if (graph.getEdgeTarget(edge).equals(startVertex)) {
            startVertex = graph.getEdgeTarget(edge);
        }
        break;
    }

    if (startVertex == null) {
        return null;
    }

    GraphPath<V, E> path = new GraphWalk<>(graph, startVertex, startVertex, new DefaultEdge());
    for (E edge : tour) {
        path.addStep(edge);
    }

    return path;
}

