public int readTag(InputStream input) throws IOException {
    int b1 = input.read();
    if (b1 == -1) {
        return 0;
    }
    int b2 = input.read();
    if (b2 == -1) {
        throw new IOException("Protocol message contained a tag with invalid wire type.");
    }
    return ((b1 & 0x7F) << 7) | (b2 & 0x7F);
}

